VALUES (2, 1, '2026-10-09 15:00Z', '2026-10-09 16:00Z', 3, 'Group project')
RETURNING id, status, version;

UPDATE bookings
SET attendees = 4, note = NULL, version = version + 1, updated_at = now()
WHERE id = 1004
RETURNING id, attendees, note, version;

UPDATE bookings
SET status = 'cancelled', cancelled_at = now(), updated_at = now()
WHERE id = 99 AND status = 'confirmed';

try {
  jdbc.sql("""
      INSERT INTO bookings (room_id, user_id, starts_at, ends_at, attendees)
      VALUES (:roomId, :userId, :startsAt, :endsAt, :attendees)
      """)
      .param("roomId", 99L)
      .param("userId", 1L)
      .param("startsAt", OffsetDateTime.parse("2026-10-07T09:00:00Z"))
      .param("endsAt", OffsetDateTime.parse("2026-10-07T10:00:00Z"))
      .param("attendees", 2)
      .update();
} catch (DataIntegrityViolationException e) {
  var cause = (SQLException) e.getMostSpecificCause();
  System.out.println(e.getClass().getSimpleName() + " " + cause.getSQLState());
  System.out.println(cause.getMessage());
}
